const rows = [
  { id: 1, orgId: "adas-bakery", number: "INV-0001" },
  { id: 2, orgId: "adas-bakery", number: "INV-0002" },
  { id: 3, orgId: "kola-motors", number: "INV-0001" },
];

function createInvoiceRepository(rows, currentOrg) {
  const org = () => {
    const id = currentOrg();
    if (!id) throw new Error("no tenant");
    return id;
  };
  return {
    list: () => rows.filter((row) => row.orgId === org()),
    get: (id) => rows.find((row) => row.id === id && row.orgId === org()),
  };
}

let current = "kola-motors";
const invoices = createInvoiceRepository(rows, () => current);
