const memberships = [
  { userId: "ada", org: "adas-bakery", role: "owner" },
  { userId: "ada", org: "kola-motors", role: "viewer" },
  { userId: "kola", org: "kola-motors", role: "owner" },
];

function loginDecision(memberships, userId, org) {
  const member = memberships.find((m) => m.userId === userId && m.org === org);
  if (!member) return { status: 403, error: "You are not a member of that organization" };
  return { status: 200, role: member.role };
}

