const responses = [
  { label: "GET /invoices/1", status: 404, body: { error: "Invoice not found" } },
  { label: "POST /invoices/1/send", status: 403, body: { error: "Access denied" } },
  { label: "GET /invoices/2", status: 404, body: { error: "Invoice not found", hint: { orgId: "adas-bakery" } } },
];

function checkIsolation(responses, attacker) {
  const orgsIn = (body) => [...JSON.stringify(body).matchAll(/"orgId":"([^"]+)"/g)].map((m) => m[1]);
  return responses
    .filter((r) => r.status !== 404 || orgsIn(r.body).some((org) => org !== attacker))
    .map((r) => r.label);
}

console.log(checkIsolation(responses, "kola-motors"));

